function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  stroke("#e08a72");
  strokeWeight(0.5);

  // Sky
  fill("#f0d9b5");
  noStroke();
  rect(0, 0, width, height / 2);

  // Hills
  fill("#d0b894");
  noStroke();
  rect(0, height / 2, width, height / 2);

  // Horizon
  fill("#b9a58b");
  noStroke();
  rect(0, height, 0, height / 2);

  // Gradient
  const gradient = createLinearGradient(0, height, width, 0);
  gradient.addColorStop(0, "#f0d9b5");
  gradient.addColorStop(1, "#b9a58b");
  fill(gradient);
  noStroke();
  rect(0, 0, width, height / 2);

  // Clouds
  fill("#e09a67");
  noStroke();
  for (let i = 0; i < 40; i++) {
    const x = random(0, width);
    const y = random(0, height / 2);
    ellipse(x, y, 4, 8);
  }

  // Trees
  fill("#a89474");
  noStroke();
  for (let i = 0; i < 16; i++) {
    const x = random(0, width);
    const y = random(0, height / 2);
    ellipse(x, y, 4, 6);
  }

  // Rocks
  fill("#9a846c");
  noStroke();
  for (let i = 0; i < 6; i++) {
    const x = random(0, width);
    const y = random(0, height / 2);
    ellipse(x, y, 2, 4);
  }

  // Sun
  fill("#ff8a65");
  noStroke();
  ellipse(width / 2, height / 2, 10, 10);
}
